        D2Common::PATH::DynamicPath::SetUnitWidth(pAllocUnit, 5);
        D2Common::PATH::DynamicPath::PATH_ChangeCollisionType(pAllocUnit->pPath.pDynamicPath, 0x8000);
        return pAllocUnit;
